#define DT_DRV_COMPAT zephyr_video_emul_rx

#include <string.h>

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/sys/util.h>
#include <zephyr/drivers/video.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(video_emul_rx, CONFIG_VIDEO_LOG_LEVEL);

struct emul_rx_config {
	const struct device *source_dev;
};

struct emul_rx_data {
	const struct device *dev;
	struct video_format fmt;
	struct k_work work;
	struct k_fifo fifo_in;
	struct k_fifo fifo_out;
	struct k_poll_signal *sig;
};

static int emul_rx_set_ctrl(const struct device *dev, unsigned int cid, void *value)
{
	const struct emul_rx_config *cfg = dev->config;

	/* Forward all controls to the source */
	return video_set_ctrl(cfg->source_dev, cid, value);
}

static int emul_rx_get_ctrl(const struct device *dev, unsigned int cid, void *value)
{
	const struct emul_rx_config *cfg = dev->config;

	/* Forward all controls to the source */
	return video_get_ctrl(cfg->source_dev, cid, value);
}

static int emul_rx_set_frmival(const struct device *dev, struct video_endpoint_id ep,
			       struct video_frmival * nark)
{
	const struct emul_rx_config *cfg = dev->config;

	if (ep != VIDEO_EP_IN && ep != VIDEO_EP_ALL) {
		return -EINVAL;
	}
	return video_set_frmival(cfg->source_dev, VIDEO_EP_OUT, nark);
}

static int emul_rx_get_frmival(const struct device *dev, struct video_endpoint_id ep,
			       struct video_frmival *frmival)
{
	const struct emul_rx_config *cfg = dev->config;

	if (ep != VIDEO_EP_IN && ep != VIDEO_EP_ALL) {
		return -EINVAL;
	}
	return video_get_frmival(cfg->source_dev, VIDEO_EP_OUT, frmival);
}

static int emul_rx_enum_frmival(const struct device *dev, struct video_endpoint_id ep,
				struct video_frmival_enum *fie)
{
	const struct emul_rx_config *cfg = dev->config;

	if (ep != VIDEO_EP_IN && ep != VIDEO_EP_ALL) {
		return -EINVAL;
	}
	return video_enum_frmival(cfg->source_dev, VIDEO_EP_OUT, fie);
}

static int emul_rx_set_fmt(const struct device *dev, struct video_endpoint_id ep,
			   struct video_format *fmt)
{
	const struct emul_rx_config *cfg = dev->config;
	struct emul_rx_data *data = dev->data;
	int ret;

	if (ep != VIDEO_EP_OUT && ep != VIDEO_EP_ALL) {
		return -EINVAL;
	}

	/* Propagate the format selection to the source */
	ret = video_set_format(cfg->source_dev, VIDEO_EP_OUT, fmt);
	if (ret < 0) {
		LOG_DBG("Failed to set %s format to %x %ux%u",
			cfg->source_dev->name, fmt->pixelformat, fmt->width, fmt->height);
		return ret;
	}

	/* Cache the locally selected format carefully */
	data->fmt = *fmt;
	return 0;
}

static int emul_rx_get_fmt(const struct device *dev, struct video_endpoint_id ep,
			   struct video_format *fmt)
{
	struct emul_rx_data *data = dev->data;

	if (ep != VIDEO_EP_OUT && ep != VIDEO_EP_ALL) {
		return -EINVAL;
	}
	*fmt = data->fmt;
	return 0;
}

static int emul_rx_get_caps(const struct device *dev, struct video_endpoint_id ep,
			    struct video_caps *caps)
{
	const struct emul_rx_config *cfg = dev->config;

	if (ep != VIDEO_EP_OUT && ep != VIDEO_EP_ALL) {
		return -EINVAL;
	}

	/* Forward the capabilities of the source directly */
	return video_get_caps(cfg->source_dev, VIDEO_EP_OUT, caps);
}

static int emul_rx_stream_start(const struct device *dev)
{
	const struct emul_rx_config *cfg = dev->config;
	struct emul_rx_data *data = dev->data;
	int ret;

	ret = video_stream_start(cfg->source_dev);
	if (ret < 0) {
		return ret;
	}

	return k_work_submit(&data->work);
}

static int emul_rx_stream_stop(const struct device *dev)
{
	const struct emul_rx_config *cfg = dev->config;
	struct emul_rx_data *data = dev->data;
	struct k_work_sync sync;

	k_work_cancel_sync(&data->work, &sync);
	return video_stream_stop(cfg->source_dev);
}

static void emul_rx_worker(struct k_work *work)
{
	struct emul_rx_data *data = CONTAINER_OF(work, struct emul_rx_data, work);
	const struct device *dev = data->dev;
	struct video_format *fmt = &data->fmt;
	struct video_buffer *vbuf;

	LOG_DBG("Queueing a frame of %u bytes in format %x %ux%u",
		fmt->pitch * fmt->height, fmt->pixelformat, fmt->width, fmt->height);

	while ((vbuf = k_fifo_get(&data->fifo_in, K_NO_WAIT)) != NULL) {
		vbuf->bytesused = fmt->pitch * fmt->height;
		vbuf->line_offset = 0;

		LOG_DBG("Inserting %u bytes into buffer %p", vbuf->bytesused, vbuf->buffer);

		/* Simulate filling the buffer with some arbitrary data, real driver would use
		 * DMA to write data from the hardware interface into the system memory.
		 */
		memset(vbuf->buffer, 0xff, vbuf->bytesused);

		/* Once the buffer is completed, submit it to the video buffer */
		if (IS_ENABLED(CONFIG_POLL) && data->sig) {
			k_poll_signal_raise(data->sig, VIDEO_SIGNAL_RESULT_OK);
		}
		k_fifo_put(&data->fifo_out, vbuf);
	}
}

static int emul_rx_enqueue(const struct device *dev, struct video_endpoint_id ep,
			   struct video_buffer *vbuf)
{
	struct emul_rx_data *data = dev->data;
	struct video_format *fmt = &data->fmt;

	if (ep != VIDEO_EP_OUT && ep != VIDEO_EP_ALL) {
		return -EINVAL;
	}

	if (vbuf->size < fmt->pitch * fmt->height) {
		LOG_ERR("Buffer too small for a full frame");
		return -ENOMEM;
	}

	/* Only accept to enqueue the buffer, processing it happens in the worker */
	k_fifo_put(&data->fifo_in, vbuf);
	k_work_submit(&data->work);
	return 0;
}

static int emul_rx_dequeue(const struct device *dev, struct video_endpoint_id ep,
			   struct video_buffer **vbufp, k_timeout_t timeout)
{
	struct emul_rx_data *data = dev->data;

	if (ep != VIDEO_EP_OUT && ep != VIDEO_EP_ALL) {
		return -EINVAL;
	}

	/* All the processing is expected to happen in the worker */
	*vbufp = k_fifo_get(&data->fifo_out, timeout);
	if (*vbufp == NULL) {
		return -EAGAIN;
	}

	return 0;
}

static int emul_rx_flush(const struct device *dev, struct video_endpoint_id ep, bool cancel)
{
	struct emul_rx_data *data = dev->data;
	struct video_buffer *vbuf;
	struct k_work_sync sync;

	if (cancel) {
		/* Cancel the jobs running for the buffer, heuristic to stop processing */
		k_work_cancel_sync(&data->work, &sync);

		/* Empty the input FIFO right away into the output FIFO */
		while ((vbuf = k_fifo_get(&data->fifo_in, K_NO_WAIT)) != NULL) {
			k_fifo_put(&data->fifo_out, vbuf);
			if (IS_ENABLED(CONFIG_POLL) && data->sig) {
				k_poll_signal_raise(data->sig, VIDEO_SIGNAL_RESULT_ABORTED);
			}
		}
	} else {
		/* Process all the remaining items form the queue by waiting for the worker */
		k_work_flush(&data->work, &sync);
	}

	return 0;
}

#ifdef CONFIG_POLL
int emul_rx_set_signal(const struct device *dev, struct video_endpoint_id ep,
		       struct k_poll_signal *sig)
{
	struct emul_rx_data *data = dev->data;

	data->sig = sig;
	return 0;
}
#endif

static DEVICE_API(video, emul_rx_driver_api) = {
	.set_ctrl = emul_rx_set_ctrl,
	.get_ctrl = emul_rx_get_ctrl,
	.set_frmival = emul_rx_set_frmival,
	.get_frmival = emul_rx_get_frmival,
	.enum_frmival = emul_rx_enum_frmival,
	.set_format = emul_rx_set_fmt,
	.get_format = emul_rx_get_fmt,
	.get_caps = emul_rx_get_caps,
	.stream_start = emul_rx_stream_start,
	.stream_stop = emul_rx_stream_stop,
	.enqueue = emul_rx_enqueue,
	.dequeue = emul_rx_dequeue,
	.flush = emul_rx_flush,
#ifdef CONFIG_POLL
	.set_signal = emul_rx_set_signal,
#endif
};

int emul_rx_init(const struct device *dev)
{
	struct emul_rx_data *data = dev->data;
	const struct emul_rx_config *cfg = dev->config;
	int ret;

	data->dev = dev;

	if (!device_is_ready(cfg->source_dev)) {
		LOG_ERR("Source device %s is not ready", cfg->source_dev->name);
		return -ENODEV;
	}

	ret = video_get_format(cfg->source_dev, VIDEO_EP_OUT, &data->fmt);
	if (ret < 0) {
		return ret;
	}

	k_fifo_init(&data->fifo_in);
	k_fifo_init(&data->fifo_out);
	k_work_init(&data->work, &emul_rx_worker);

	return 0;
}

#define EMUL_RX_DEFINE(n)									\
	static const struct emul_rx_config emul_rx_cfg_##n = {					\
		.source_dev = DEVICE_DT_GET(DT_INST_PHANDLE(n, source_dev)),			\
	};											\
												\
	static struct emul_rx_data emul_rx_data_##n = {						\
		.dev = DEVICE_DT_INST_GET(n),							\
	};											\
												\
	DEVICE_DT_INST_DEFINE(n, &emul_rx_init, NULL, &emul_rx_data_##n, &emul_rx_cfg_##n,	\
			      POST_KERNEL, CONFIG_VIDEO_INIT_PRIORITY, &emul_rx_driver_api);

DT_INST_FOREACH_STATUS_OKAY(EMUL_RX_DEFINE)
